/**
 * dsh-mcp-manager — erasure/impl/guard/index.ts：tools:sdk 段的 mcp__ 声明级擦除。
 *
 * 承重约束（三条，判据都在 test/unit/unit-erasure.test.ts）：
 *
 * 1. 只擦行首声明：SDK 生成的 TS 声明里 mcp__ 工具名恒在行首（去缩进后），
 *    散文里的 mcp__ 提及不在行首，故不受影响；段外文本本函数碰不到——
 *    调用方只把 tools:sdk 段的文本递进来。
 * 2. 注释连带：SDK 每条声明自带文档注释，擦声明时把紧贴其上的注释与空行
 *    一并带走，不留无主注释；非 mcp__ 条目的注释原样保留。
 * 3. 花括号深度跟踪：输出映射块按 brace 深度收口，渲染嵌套加深也不提前收口、
 *    更不误删块外行；未知形状宁可保留也不损坏文本（保留分支无计数：warn 只统计成功擦除数，未知形状覆盖靠单测形状断言，漂移即红）。
 */
import type { StartSdkErasureArgs } from "../../interface.ts";

/** 宿主 tools:sdk 分节名（dsh-tools sdkSection 的注册名，本包只读不拥有）。 */
const SDK_SECTION_NAME = "tools:sdk";

/** 注册名前缀（与 server/shared/tool-names.ts 的派生点同源，这里只读不造名）。 */
const MCP_PREFIX = "mcp__";

/** 累计计数（warn 里携带，根因修复前窗口统计不丢失）。 */
export interface ErasureStats {
  rounds: number;
  declarations: number;
}

/** 单次擦除结果。 */
export interface ErasureResult {
  text: string;
  erased: number;
}

/**
 * 可附着行：文档注释行或空行。暂存，见分晓后再决定去留——后面若紧跟 mcp__ 声明
 * 则连带擦掉，否则原样吐回（注释归属判定只看紧邻，不做跨行语义分析）。
 */
function isAttachableLine(line: string): boolean {
  const text = line.trimStart();
  return (
    text === "" ||
    text.startsWith("/**") ||
    text.startsWith("*/") ||
    text.startsWith("* ") ||
    text === "*"
  );
}

/**
 * 行首声明的 mcp__ 工具名；非声明行返回 undefined。
 * 散文提及（如指导文案里的 mcp__）不在行首，天然豁免。
 */
function mcpDeclName(line: string): string | undefined {
  const text = line.trimStart();
  if (!text.startsWith(MCP_PREFIX)) return undefined;
  const rest = text.slice(MCP_PREFIX.length);
  const sep = rest.indexOf(":");
  if (sep <= 0) return undefined;
  const name = rest.slice(0, sep);
  if (name.length === 0) return undefined;
  for (const ch of name) {
    const word =
      (ch >= "a" && ch <= "z") ||
      (ch >= "A" && ch <= "Z") ||
      (ch >= "0" && ch <= "9") ||
      ch === "_";
    if (!word) return undefined;
  }
  return name;
}

/** 行内花括号净增量（输出映射块收口跟踪用；只数字面量比较）。 */
function braceDelta(line: string): number {
  return line.split("{").length - line.split("}").length;
}

/**
 * 擦掉 SDK 文本里全部行首 mcp__ 声明（值声明与输出映射块）及其附着注释。
 * 未知形状的行一律保留且不计数（warn 只覆盖成功擦除；未知形状由单测形状断言覆盖）：误删则直接损坏提示词。
 */
export function eraseMcpSdkDeclarations(text: string): ErasureResult {
  const lines = text.split("\n");
  const kept: string[] = [];
  let pending: string[] = [];
  let erased = 0;
  let depth = 0;
  const flushPending = (): void => {
    for (const line of pending) kept.push(line);
    pending = [];
  };
  for (const line of lines) {
    if (depth > 0) {
      depth += braceDelta(line);
      if (depth <= 0) depth = 0;
      continue;
    }
    if (isAttachableLine(line)) {
      pending.push(line);
      continue;
    }
    const name = mcpDeclName(line);
    if (name === undefined) {
      flushPending();
      kept.push(line);
      continue;
    }
    const after = line.slice(line.indexOf(":") + 1).trim();
    if (after === "unknown;") {
      pending = [];
      erased += 1;
      continue;
    }
    if (after === "{") {
      pending = [];
      erased += 1;
      depth = 1;
      continue;
    }
    flushPending();
    kept.push(line);
  }
  flushPending();
  return { text: kept.join("\n"), erased };
}

/**
 * 启动装配侧兜底擦除：订阅宿主组装 waterfall，对下游结果的 tools:sdk 段做声明级擦除。
 * 无泄漏时原样返回下游结果（同一引用，不制造装配抖动）；有泄漏时返回替换了该段文本
 * 的新装配，并 warn 一次（累计计数见 ErasureStats 语义，根因未修前统计不丢）。
 */
export function startSdkErasure(args: StartSdkErasureArgs): () => void {
  const { assemble, logger } = args;
  const stats: ErasureStats = { rounds: 0, declarations: 0 };
  return assemble.onAssemble(async (_assembly, _context, next) => {
    const downstream = await next();
    // 上游其他监听可能在运行时改写形状（宿主类型只约束编译期），先守形状再动手。
    if (!Array.isArray(downstream.sections)) return downstream;
    let roundErased = 0;
    const nextSections = downstream.sections.map((section) => {
      // 上游监听运行在类型之外：空段与异形段直接透传，绝不在此抛（抛即短路整条 waterfall）。
      if (typeof section !== "object" || section === null) return section;
      if (section.name !== SDK_SECTION_NAME || typeof section.text !== "string") return section;
      const result = eraseMcpSdkDeclarations(section.text);
      if (result.erased === 0) return section;
      roundErased += result.erased;
      return { ...section, text: result.text };
    });
    if (roundErased === 0) return downstream;
    stats.rounds += 1;
    stats.declarations += roundErased;
    logger.warn(
      "dsh-mcp-manager: erased " +
        roundErased +
        " leaked mcp__ declaration(s) from tools:sdk (round " +
        stats.rounds +
        ", total " +
        stats.declarations +
        "; transient registration race, see #922)",
    );
    return { ...downstream, sections: nextSections };
  });
}

packages/dsh-mcp-manager/src/server/inje.source:
/**
 * dsh-mcp-manager — inject/impl/call-timeout/index.ts：中间层外层超时纯函数（#935）。
 *
 * 回答「`ws_mcp_call` 注册时的 `timeoutMs` 该是多少？」——取在用全量源里最大的单次调用
 * 预算，再叠一段内部尾。调用方（组合根）负责收集全量源（`mw.units` 全 root 含 `@global`
 * 的连接条目 + `manager.runtimeRegistry` 内存注入项），本函数只做纯计算，便于单测。
 *
 * 两段尾不要混淆：
 * - 内层尾 +2s：dispatch 执行器给每次调用套的 `withTimeout` 兜底预算 = 该源
 *   `toolCallTimeoutMs` + 2000（见 servers/dispatch/impl/call）；
 * - 外层尾 +25s：本函数在最大源预算上叠的内部尾 = `CONNECT_TIMEOUT_MS`(10s) +
 *   `DISCOVERY_TIMEOUT_MS`(10s) + 5000。外层恒大于任何一源的内层预算，1 分钟以上的
 *   长调用不再被外层先误杀。
 *
 * 本文件零依赖：三个字面量是 `server/shared/constants.ts` 里 `DEFAULT_TOOL_CALL_TIMEOUT_MS` /
 * `CONNECT_TIMEOUT_MS` / `DISCOVERY_TIMEOUT_MS` 与 `+ 5000` 的镜像——共享层落在 config 域的
 * 模块求值路径上只能是无 import 叶子，本函数同理保持无 import（改共享常量时同步改这里，
 * `unit-call-timeout` 的「外层公式断言」用常量现算期望值、不用字面量，会当场打红）。
 *
 * @param sources 全量源的 `toolCallTimeoutMs` 原值（含缺省缺席 `undefined`，非法值按缺省计）。
 * @returns 外层 `timeoutMs`：`max(源，缺省 15s) + 25s`；空集回落 40s（= 缺省 15s + 25s）。
 */
const DEFAULT_SOURCE_TIMEOUT_MS = 15_000;
const OUTER_TAIL_MS = 10_000 + 10_000 + 5000;

export function resolveMiddlewareCallTimeoutMs(sources: readonly (number | undefined)[]): number {
  let max = DEFAULT_SOURCE_TIMEOUT_MS;
  for (const timeout of sources) {
    if (typeof timeout === "number" && Number.isFinite(timeout) && timeout > max) {
      max = timeout;
    }
  }
  return max + OUTER_TAIL_MS;
}

/**
 * dsh-mcp-manager — inject/impl/image-admission/index.ts：ws_mcp_call 的 **A+ 自持图片准入**
 * （#767 笔 1b 交付物 B）。
 *
 * 背景：本包把远端转发改道宿主的 `ctx.tools.execute` 之后，官方执行器那次图片准入（它读
 * `exec.agent` 解模型路由）随 F4 收口一起去掉了——远端图片结果原本能落成真附件，去掉 agent 后
 * 只能退化成 `[image content]`。本模块把那次准入在本包内补回来：解模型路由 → 白名单解码 →
 * `attachments.saveImages` → 经官方 `finalizeContent` 接缝把模型面内容换成真附件块。
 *
 * 判定顺序与文案**照官方 dsh-mcp-client 的 implement**（`resolveImageAdmission` /
 * `prepareImageProjection` / `imageDiagnostic`，逐字段一致，主控已逐条核实）；任何拒绝都只
 * 降级成诊断文本、不抛——图片落不了库不该让一次工具调用失败。
 *
 * 本模块是纯逻辑（不 import 任何域内实现）：文本块的渲染规则由接线点按实参递进来
 * （middleware-register 的 `formatCallContentBlock`），避免两处各写一份占位规则而漂移。
 */
import type {
  AttachmentsPort,
  ModelContentBlock,
  ModelInfoPort,
  SaveImageInput,
} from "../../../shared/interface.ts";

/** 官方四值白名单（本地 store 会把 PNG 转码成 WebP，故返回的 mediaType 可能与之不同）。 */
const IMAGE_MEDIA_TYPES: readonly string[] = ["image/png", "image/jpeg", "image/webp", "image/gif"];

/** canonical base64：官方同款正则，且要求 decode→encode 往返逐字节相等（拒绝别名形态）。 */
const CANONICAL_BASE64 = /^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$/;

/**
 * 单张解码上限 8 MiB（#903 B-M1 DoS 面：远端结果来自可信服务器也可能作恶，
 * 超大 base64 解码即占内存）。超限与非法同路——进 validationErrors 走既有整批诊断降级。
 */
const MAX_IMAGE_BYTES = 8 * 1024 * 1024;

/**
 * 单次结果图片数上限（#903 B-M1：批量下发数百张即 O(n) 解码+落库）。超限整批转诊断，
 * 在解码前判定——一字节都不解。
 */
const MAX_IMAGES_PER_RESULT = 10;

/** 图片准入要用的两条宿主能力：**晚读** thunk（服务可能缺席，且 apply 期取不到）。 */
export interface ImageAdmissionFaces {
  readonly attachments: () => AttachmentsPort | undefined;
  readonly models: () => ModelInfoPort | undefined;
}

/** 一次准入请求的全部输入。 */
export interface ImageAdmissionRequest {
  /** 外层调用身份：模型自己的 agent（不受我方 deny 影响），用于解当前模型路由。 */
  readonly agent: unknown;
  /** 待投影的**远端原始** content（必须是你 return 的那个 value 的 content，含 stale 前置提示）。 */
  readonly content: readonly unknown[];
  readonly signal: AbortSignal | undefined;
  readonly faces: ImageAdmissionFaces;
  /** 非图片块的文本化规则（接线点传 formatCallContentBlock，单一实现）。 */
  readonly formatBlock: (block: unknown) => string;
}

/** 当前模型路由（provider + model）。 */
export interface ImageRoute {
  readonly provider?: string;
  readonly model?: string;
}

function recordOf(value: unknown): Record<string, unknown> | undefined {
  return typeof value === "object" && value !== null && !Array.isArray(value)
    ? (value as Record<string, unknown>)
    : undefined;
}

function stringOf(value: unknown): string | undefined {
  return typeof value === "string" && value !== "" ? value : undefined;
}

/**
 * 远端**原始**图片块的判据：`type === "image"` 且 `data` 是字符串。
 *
 * `typeof data === "string"` 这一半是承重的：本包自己产出的模型面图片块是
 * `{type:"image", attachment}`（没有 `data`），用这个判据天然把它排除，不会二次准入。
 */
export function isRemoteImageBlock(block: unknown): boolean {
  const rec = recordOf(block);
  return rec !== undefined && rec.type === "image" && typeof rec.data === "string";
}

/** content 里是否存在远端原始图片块（不存在 → 不建投影，结果面逐字节不变）。 */
export function containsRemoteImage(content: readonly unknown[]): boolean {
  return content.some(isRemoteImageBlock);
}

/**
 * 解当前模型路由：会话最近一次 `request/header` 快照里的 config 优先，回落到 agent 的静态
 * options（官方 `resolveImageAdmission` 的取法）。任何一环取不到都给 `undefined`，由调用方
 * 归到 "the current model route could not be resolved"。
 */
export function resolveRoute(agent: unknown): ImageRoute {
  const agentRecord = recordOf(agent);
  const session = recordOf(agentRecord?.session);
  let routedConfig: Record<string, unknown> | undefined;
  if (session !== undefined && typeof session.requestHeader === "function") {
    try {
      // 必须带 receiver 调用：requestHeader 读实例字段（this.headerFold），裸引用会丢 this。
      const header = (session.requestHeader as () => unknown).call(session);
      routedConfig = recordOf(recordOf(header)?.config);
    } catch {
      // 会话尚未产出 header 快照 / 假 agent：回落静态 options。
      routedConfig = undefined;
    }
  }
  const options = recordOf(agentRecord?.options);
  return {
    provider: stringOf(routedConfig?.provider) ?? stringOf(options?.provider),
    model: stringOf(routedConfig?.model) ?? stringOf(options?.model),
  };
}

/** 稳定诊断文案（官方逐字）。 */
function imageDiagnostic(block: Record<string, unknown>, reason: string): string {
  const mediaType = typeof block.mimeType === "string" ? block.mimeType : "unknown media type";
  return `[image unavailable: ${mediaType}; ${reason}; raw image data remains available to programmatic callers]`;
}

/** 解码一个远端图片块（不接受 base64 别名）。 */
function decodeImage(block: Record<string, unknown>): SaveImageInput {
  const mediaType = block.mimeType;
  if (typeof mediaType !== "string" || !IMAGE_MEDIA_TYPES.includes(mediaType)) {
    throw new Error("the declared media type is not PNG, JPEG, WebP, or GIF");
  }
  const data = block.data;
  if (typeof data !== "string") {
    throw new Error("the image data is not canonical base64");
  }
  // #903 B-M1：canonical 正则在数 MB 输入上回溯爆栈（实测 8MB 输入抛
  // Maximum call stack size exceeded）——16MB base64 必超 8MiB 解码上限，直接硬拒，
  // 不进正则不解码；1MB 以上跳过正则、只用解码往返判定（文案一致）。
  if (data.length > MAX_IMAGE_BYTES * 2) {
    throw new Error("the image data exceeds 8 MiB");
  }
  if (data.length <= 1024 * 1024 && !CANONICAL_BASE64.test(data)) {
    throw new Error("the image data is not canonical base64");
  }
  const bytes = Buffer.from(data, "base64");
  if (bytes.toString("base64") !== data) {
    throw new Error("the image data is not canonical base64");
  }
  if (bytes.length > MAX_IMAGE_BYTES) {
    throw new Error("the image data exceeds 8 MiB");
  }
  return {
    data: bytes,
    mediaType: mediaType as SaveImageInput["mediaType"],
  };
}

/** 解析准入并交出附件库（官方判定顺序：attachments → 路由 → llm → 模态 → signal）。 */
async function resolveAdmission(
  faces: ImageAdmissionFaces,
  agent: unknown,
  signal: AbortSignal | undefined,
): Promise<AttachmentsPort> {
  const attachments = faces.attachments();
  if (attachments === undefined) throw new Error("no attachment store is mounted");
  const route = resolveRoute(agent);
  const models = faces.models();
  if (route.provider === undefined || route.model === undefined || models === undefined) {
    throw new Error("the current model route could not be resolved");
  }
  let info: { inputModalities?: readonly string[] };
  try {
    info = await models.resolveModelInfo(route.provider, route.model, signal);
  } catch {
    throw new Error("the current model route could not be verified");
  }
  if (info.inputModalities === undefined || !info.inputModalities.includes("image")) {
    throw new Error(`model "${route.model}" does not declare image input`);
  }
  if (signal?.aborted === true) throw new Error("the tool call was canceled before image storage");
  return attachments;
}

/** 按原位置投影：远端图片块换成 image/诊断块，其余块仍走接线点给的文本规则。 */
function projectContent(
  content: readonly unknown[],
  formatBlock: (block: unknown) => string,
  image: (block: Record<string, unknown>, index: number) => ModelContentBlock,
): ModelContentBlock[] {
  const projected: ModelContentBlock[] = [];
  for (const [index, block] of content.entries()) {
    if (isRemoteImageBlock(block)) {
      projected.push(image(recordOf(block) as Record<string, unknown>, index));
      continue;
    }
    projected.push({ type: "text", text: formatBlock(block) });
  }
  return projected;
}

/**
 * 把远端结果里的图片块准入成模型面内容。
 *
 * @returns 完整模型面投影（文本块 + 原位图片/诊断块）；**没有远端原始图片块时返回 `undefined`**
 *   ——调用方据此不建映射，结果面继续走 `render`（既有行为逐字节不变）。
 */
export async function projectImageAdmission(
  request: ImageAdmissionRequest,
): Promise<ModelContentBlock[] | undefined> {
  const { agent, content, signal, faces, formatBlock } = request;
  if (!containsRemoteImage(content)) return undefined;

  // 批量上限先行（#903 B-M1）：超限整批转诊断，一字节都不解。
  let remoteCount = 0;
  for (const block of content) if (isRemoteImageBlock(block)) remoteCount += 1;
  if (remoteCount > MAX_IMAGES_PER_RESULT) {
    const reason = `too many images in one result (>${MAX_IMAGES_PER_RESULT})`;
    return projectContent(content, formatBlock, (block) => ({
      type: "text",
      text: imageDiagnostic(block, reason),
    }));
  }

  const imageIndexes: number[] = [];
  const decoded: SaveImageInput[] = [];
  const validationErrors = new Map<number, string>();
  for (const [index, block] of content.entries()) {
    if (!isRemoteImageBlock(block)) continue;
    imageIndexes.push(index);
    try {
      decoded.push(decodeImage(recordOf(block) as Record<string, unknown>));
    } catch (error) {
      validationErrors.set(index, error instanceof Error ? error.message : String(error));
    }
  }
  // 任一解码失败 → 整批转文本诊断（含「同批另一张非法」这条归因）。
  if (validationErrors.size > 0) {
    return projectContent(content, formatBlock, (block, index) => ({
      type: "text",
      text: imageDiagnostic(
        block,
        validationErrors.get(index) ?? "another image in the same result was invalid",
      ),
    }));
  }

  let attachments: AttachmentsPort;
  try {
    attachments = await resolveAdmission(faces, agent, signal);
  } catch (error) {
    const reason = error instanceof Error ? error.message : String(error);
    return projectContent(content, formatBlock, (block) => ({
      type: "text",
      text: imageDiagnostic(block, reason),
    }));
  }

  try {
    const refs = await attachments.saveImages(decoded);
    const byIndex = new Map(imageIndexes.map((index, offset) => [index, refs[offset]]));
    return projectContent(content, formatBlock, (block, index) => {
      const ref = byIndex.get(index);
      // 落库返回值比入参短（实现违约）时按拒绝处理：模型面不允许出现 attachment 为空的图片块。
      return ref === undefined
        ? {
            type: "text",
            text: imageDiagnostic(block, "durable image storage rejected the result"),
          }
        : { type: "image", attachment: ref };
    });
  } catch {
    // 落库失败不抛（官方区分 ImageAdmissionError 与一般存储错误；本包不引 dsh-attachment，
    // 故统一用后者那条更保守的文案）。
    return projectContent(content, formatBlock, (block) => ({
      type: "text",
      text: imageDiagnostic(block, "durable image storage rejected the result"),
    }));
  }
}

/**
 * dsh-mcp-manager — inject/impl/service/index.ts：工具注册域端口持有者（#767 B2a-wire W6）。
 *
 * 域内实现经 `injectPorts.get()` 取数，写入只发生在组合根入口顶层的 `installInject`
 * （见 `src/index.ts`）。形态照 `catalog/impl/service/` 与 `pipeline/impl/service/`：
 * 模块级只有一个 `const` 实例、状态收进实例字段（I9），装配与复位只经方法（方法内赋值）。
 */
import type { InjectDeps } from "../../deps.ts";

/** 工具注册域端口表：装配一次、域内多处读。 */
class InjectPorts {
  /** 未装配时保持 undefined——「没装配」与「装配了空实现」必须可区分（I6）。 */
  private deps: InjectDeps | undefined;

  /** 装配：组合根递入静态模块引用；重复装配是编程错误，当场暴露。 */
  install(deps: InjectDeps): void {
    if (this.deps !== undefined) throw new Error("dsh-mcp-manager: inject 域只能装配一次");
    this.deps = deps;
  }

  /** 卸载：只复位装配标记，本域没有别的活资源要释放。 */
  release(): void {
    this.deps = undefined;
  }

  /**
   * 域内取数的唯一入口。未装配即抛错而不是回落默认值：默认值会让「组合根漏装」表现成行为
   * 正常但参数不对（检索族与策略裁决静默换实现），症状与本插件毫无字面关联。
   */
  get(): InjectDeps {
    const deps = this.deps;
    if (deps === undefined) {
      throw new Error(
        "dsh-mcp-manager: inject 域未装配——组合根未在入口调用 installInject（src/index.ts）",
      );
    }
    return deps;
  }
}

/** 本域唯一的装配实例：类不外放，外部 new 不出第二份端口表。 */
export const injectPorts = new InjectPorts();

/**
 * dsh-mcp-manager — 中间层工具注册（ws_mcp_search / ws_mcp_call /
 * ws_mcp_list / ws_mcp_detail + 策略 guard）。
 *
 * 注册四个中间层工具与工具级禁用 guard 层；类型面自各域门面（store/interface.ts 的
 * DisabledToolsMap）与 stats/interface.ts（McpStatsCollector）取，连接池类
 * McpMiddleware 自
 * connection/runtime/interface.ts 只作 `import type`（防运行值环）。跨域取数一律经
 * `injectPorts.get()`（端口声明见 ../deps.ts）——catalog 检索族、pipeline
 * 裁决族与超时兜底、workspace 全名解析，本文件对四个提供域没有值 import。外层调用超时
 * 不再读 runtime 限额口（#935）：组合根按全量源现算经 options.callTimeoutMs 递入。跨端契约常量
 * MIDDLEWARE_GLOBAL_ROOT 与值常量 LIST_DEFAULT_TOOLS_PER_SERVER 直接取自共享层门面（W3b 迁移）。
 * 全局可见性（评审 A）：search/list/detail 恒合并查询「项目 root 单元 + @global 单元」；
 * call 放行 @global root。单池（#767 笔 1a/笔 2）后没有模式分支。
 */

import type { Context } from "@deepseek-ai/cordis";
import type { ToolDefinition, ToolExecution, PreToolDecision } from "@deepseek-ai/dsh-tools";
import type { McpMiddleware } from "../connection/runtime/interface.ts";
import { LIST_DEFAULT_TOOLS_PER_SERVER } from "../shared/interface.ts";
import type { ModelContentBlock } from "../shared/interface.ts";
import { MIDDLEWARE_GLOBAL_ROOT } from "../../shared/interface.ts";
import type { McpStatsCollector } from "../stats/interface.ts";
import type { DisabledToolsMap } from "../store/interface.ts";
import { injectPorts } from "./impl/service/index.ts";
import { projectImageAdmission, type ImageAdmissionFaces } from "./impl/image-admission/index.ts";
import { resolveMiddlewareCallTimeoutMs } from "./impl/call-timeout/index.ts";

/**
 * #770-A4 统计落盘脱敏：回答「stats.json 的 lastError 怎么不存明文？」——收集器
 * （McpStatsCollector）保持纯（不引 pipeline），调用方（本文件 executeCall 的
 * catch）在传入前先脱敏：复用 C 快照（mw.host.redactionServers()，manager
 * .getRedactionServers 的展开后快照）+ pipeline.createRedactor。脱敏失败时回落
 * 省略 lastError（仍计 errors，不把原文落盘）。
 *
 * 模块函数而非类成员：本文件无类，纯函数便于单测直调（不经完整工具注册链）。
 */
function redactedStatsError(mw: McpMiddleware, error: unknown): string | undefined {
  try {
    const {
      pipeline: { msgOf, createRedactor },
    } = injectPorts.get();
    const redactor = createRedactor([...mw.host.redactionServers()]);
    return redactor(new Error(msgOf(error))).slice(0, 200);
  } catch {
    return undefined;
  }
}

/** 工具执行与组装上下文。 */
interface MiddlewareToolContext {
  mw: McpMiddleware;
  resolveRoot: (agent: unknown) => Promise<string | undefined>;
  stats?: McpStatsCollector;
  /**
   * A+ 图片准入的模型面投影表。键是**本次 exec 对象身份**（宿主在 `execute` 与
   * `finalizeContent` 之间递的是同一个对象，官方也以它做 WeakMap 键）——不用模块级单例，
   * 并发调用之间不会串投影。
   */
  projections: WeakMap<ToolExecution, ModelContentBlock[]>;
  /** 图片准入要用的宿主能力（晚读 thunk）；接线点省略时退化成纯诊断（不抛）。 */
  faces: ImageAdmissionFaces;
}

/** 空 query 搜索无命中时的可归因提示（纯 render 文案，C 项）。 */
const SEARCH_EMPTY_HINT =
  "(No matching MCP tools found in current workspace; use ws_mcp_list for full inventory or verify server/tool names before searching)";

/**
 * 项目级可见服务器名列表（A1 归因文案用；排序去重）。
 *
 * 数据源是 catalog 域的目录读口（#767 S1-3b）：`units` 已不再持目录，根过滤由读口自己做
 * ——单元在册但目录没有任何服务器时给空表，与「单元不在册」在下游都不产生文案差异。
 */
function visibleProjectServers(root: string): string[] {
  const { catalog } = injectPorts.get();
  return [...new Set(catalog.catalogDirectory.serverNamesFor(root))].sort();
}

/** 等待 in-flight 连接/发现（8s 预算，与 search 对齐；超时不阻塞返回已有目录）。 */
async function waitForDiscovery(
  unit: NonNullable<Awaited<ReturnType<McpMiddleware["projectUnitFor"]>>>,
): Promise<void> {
  const {
    pipeline: { withTimeout },
  } = injectPorts.get();
  const inflight = [...unit.inFlight.values()];
  if (inflight.length === 0) return;
  try {
    await withTimeout(Promise.allSettled(inflight), 8000, "等待连接/发现超时");
  } catch {
    // 超时不阻塞（返回已有目录）
  }
}

/**
 * 可见单元集合：项目 root + @global（评审 A 全局可见性修复）。
 * root 本身为 @global 时去重（防无项目 cwd 下服务器翻倍）。
 *
 * 单池（#767 笔 1a）：@global 恒可见——「按模式合并」的分支已删。
 */
function visibleMiddlewareRoots(root: string | undefined): string[] {
  if (root === undefined) return [];
  return root === "@global" ? ["@global"] : [root, "@global"];
}

/**
 * 路由一致性校验（detail/call 共用；A2）：目标 root 必须等于当前 root，或 @global
 * （全局配置跨工作空间共享，语义成立）。
 *
 * 单池（#767 笔 1a）：原「@global 且非 all 模式 → 拒绝」那道门已删——可达性
 * 三件套之一。全局服务器不再有 mcp__ 直呼面，@global 必须对所有调用方可达。
 * 「其他 root（≠ 当前 root 且 ≠ @global）恒拒」逐字保持（防跨空间串台）。
 * @returns 校验通过的 root；抛错则拒绝。
 */
async function checkMiddlewareRoot(
  caller: string,
  server: string,
  root: string,
): Promise<string | undefined> {
  const {
    workspace: { parseFullServerName },
  } = injectPorts.get();
  const parsed = parseFullServerName(server);
  if (parsed === undefined) {
    throw new Error(`${caller}: server 参数格式非法，应为 @<root>/<server>`);
  }
  if (parsed.root !== root && parsed.root !== MIDDLEWARE_GLOBAL_ROOT) {
    throw new Error(
      `${caller}: server ${JSON.stringify(server)} 不属于当前工作空间 ${JSON.stringify(root)}；路由一致性校验失败（防跨空间串台）`,
    );
  }
  return parsed.root;
}

// ---------------------------------------------------------------------------
// 1. ws_mcp_search
// ---------------------------------------------------------------------------

function formatSearchHit(hit: Record<string, unknown>): string {
  const server = String(hit.server ?? "");
  const tool = String(hit.tool ?? "");
  const description = String(hit.description ?? "");
  return `${server}/${tool}: ${description}`;
}

function formatUnavailableServer(entry: Record<string, unknown>): string {
  return `${String(entry.server ?? "")}: ${String(entry.reason ?? "")}`;
}

function renderSearchOutput(_args: unknown, value: unknown) {
  const v = (value ?? {}) as {
    results?: Array<Record<string, unknown>>;
    unavailable?: Array<Record<string, unknown>>;
    truncated?: unknown;
  };
  const lines = (v.results ?? []).map(formatSearchHit);
  let body = lines.length > 0 ? lines.join("\n") : SEARCH_EMPTY_HINT;
  if (v.truncated === true) {
    body +=
      "\n(Results reached limit and may be incomplete — increase limit or use ws_mcp_list for full audit)";
  }
  const unavailable = (v.unavailable ?? []).map(formatUnavailableServer);
  const text =
    unavailable.length > 0 ? `${body}\n\nUnavailable servers:\n${unavailable.join("\n")}` : body;
  return [{ type: "text" as const, text }];
}

function parseSearchParams(args: unknown): { query: string; serverFilter?: string; limit: number } {
  const params = (typeof args === "object" && args !== null ? args : {}) as Record<string, unknown>;
  const query = typeof params.query === "string" ? params.query : "";
  const serverFilter = typeof params.server === "string" ? params.server : undefined;
  const requested = typeof params.limit === "number" ? Math.floor(params.limit) : 5;
  const limit = Math.max(1, Math.min(requested, 10));
  return { query, serverFilter, limit };
}

async function executeSearch(
  toolCtx: MiddlewareToolContext,
  args: unknown,
  exec: { signal?: AbortSignal; agent?: unknown },
) {
  const root = await toolCtx.resolveRoot(exec.agent);
  if (root === undefined) throw new Error("ws_mcp_search: 无法确定工作空间，请先选择工作区");
  const { query, serverFilter, limit } = parseSearchParams(args);
  if (toolCtx.stats?.isEnabled()) {
    toolCtx.stats.recordSearch(query);
  }
  const roots = visibleMiddlewareRoots(root);
  const unit = await toolCtx.mw.projectUnitFor(root);
  if (unit === undefined) {
    return { results: [], unavailable: [], truncated: false };
  }
  // 等待 in-flight 连接/发现（预算内），再搜索。对可见全部单元
  // （含 @global 首次触达）都等待——否则全局目录首次为空（P1-3 修复）。
  for (const visible of roots) {
    const visibleUnit = visible === root ? unit : await toolCtx.mw.projectUnitFor(visible);
    if (visibleUnit !== undefined) await waitForDiscovery(visibleUnit);
  }
  const {
    catalog: { searchCatalogMulti },
  } = injectPorts.get();
  const { results, unavailable, truncated } = searchCatalogMulti(
    toolCtx.mw.units,
    roots,
    query,
    limit,
  );
  // truncated 由检索函数返回截断事实（恰好命中 limit 不误报，B10 修正——
  // 旧实现按过滤前 results.length >= limit 判定，恰恰等于 limit 也误报
  // 「可能未列全」）；serverFilter 过滤在截断判定之后，纯展示层过滤。
  const filtered =
    serverFilter === undefined ? results : results.filter((hit) => hit.server === serverFilter);
  return { results: filtered, unavailable, truncated };
}

function buildSearchTool(toolCtx: MiddlewareToolContext): ToolDefinition {
  return {
    name: "ws_mcp_search",
    description:
      "Search workspace MCP tools catalog by keyword (matches server, tool, description, and parameter names). Search first, then invoke with ws_mcp_call; use ws_mcp_list for full inventory audits. Empty query returns capability summary.",
    parameters: {
      type: "object",
      properties: {
        query: {
          type: "string",
          description: "Search query / keywords; empty returns capability summary",
        },
        server: { type: "string", description: "Optional: @<root>/<server> full name filter" },
        limit: { type: "number", description: "Max results to return (default 5, max 10)" },
      },
    },
    output: {
      schema: {
        type: "object",
        properties: {
          results: { type: "array", items: {} },
          unavailable: { type: "array", items: {} },
          truncated: {
            type: "boolean",
            description:
              "结果是否因 limit 截断（results 达到 limit 时为 true，提示模型可能未列全）",
          },
        },
        required: ["results", "unavailable", "truncated"],
        additionalProperties: false,
      },
      render: renderSearchOutput,
    },
    isConcurrencySafe: () => true,
    execute: (args, exec) => executeSearch(toolCtx, args, exec),
  };
}

// ---------------------------------------------------------------------------
// 2. ws_mcp_call
// ---------------------------------------------------------------------------

function formatCallContentBlock(block: unknown): string {
  if (typeof block !== "object" || block === null) {
    return "[unsupported MCP content]";
  }
  const rec = block as Record<string, unknown>;
  if (rec.type === "text" && typeof rec.text === "string") {
    return rec.text;
  }
  if (rec.type === "resource" || rec.type === "resource_link") {
    return "[resource: content discarded]";
  }
  return `[${String(rec.type ?? "unknown")} content]`;
}

function renderCallOutput(_args: unknown, value: unknown) {
  const v = (value ?? {}) as { content?: unknown };
  const content = Array.isArray(v.content) ? v.content : [];
  const parts = content.map(formatCallContentBlock);
  return [
    {
      type: "text" as const,
      text: parts.length > 0 ? parts.join("\n") : "(MCP tool returned no content)",
    },
  ];
}

function parseCallParams(args: unknown): { server: string; tool: string; arguments?: unknown } {
  const params = (typeof args === "object" && args !== null ? args : {}) as Record<string, unknown>;
  const server = typeof params.server === "string" ? params.server : "";
  const tool = typeof params.tool === "string" ? params.tool : "";
  return { server, tool, arguments: params.arguments };
}

async function executeCall(
  toolCtx: MiddlewareToolContext,
  args: unknown,
  /**
   * 完整执行身份。为什么不是 `Pick<ToolRunContext, ...>`：图片准入的投影要以**本 exec 对象**
   * 为键存进 WeakMap，而 `finalizeContent` 收到的是 `ToolExecution`——两处必须是同一个类型，
   * 否则同一对象在两侧被读成不同形状（`ToolRunContext extends ToolExecution`，收窄无损）。
   */
  exec: ToolExecution,
) {
  const root = await toolCtx.resolveRoot(exec.agent);
  if (root === undefined) throw new Error("ws_mcp_call: 无法确定工作空间，请先选择工作区");
  const { server, tool, arguments: callArguments } = parseCallParams(args);
  if (server === "" || tool === "") throw new Error("ws_mcp_call: server 与 tool 均为必填");
  const {
    workspace: { parseFullServerName },
  } = injectPorts.get();
  const parsed = parseFullServerName(server);
  if (parsed === undefined)
    throw new Error("ws_mcp_call: server 参数格式非法，应为 @<root>/<server>");
  const targetRoot = await checkMiddlewareRoot("ws_mcp_call", server, root);
  if (targetRoot === undefined) {
    throw new Error(
      `ws_mcp_call: server ${JSON.stringify(server)} 不属于当前工作空间 ${JSON.stringify(root)}；路由一致性校验失败（防跨空间串台）`,
    );
  }
  const unit = await toolCtx.mw.projectUnitFor(targetRoot);
  if (unit === undefined)
    throw new Error(`ws_mcp_call: 工作空间 ${JSON.stringify(targetRoot)} 无项目级 MCP 配置`);
  await toolCtx.mw.ensureConnected(targetRoot, parsed.server);
  // #767 笔 1b 交付物 C（F4 收口）：这里的 agent 交给 dispatch 后**只服务封装直呼分支**
  // （它的 execute 依赖 agent.session.header.cwd 做 projectPath 补全）；远端转发分支不再携带
  // agent（去 agent 后官方那次图片准入退化成本包自持的 image-admission，见 executeCall 尾部）。
  // callId/rootCallId/token 供 dispatch 合成子调用 id 并透传 parent（#767 S1-4d）。
  const startTime = Date.now();
  let value: unknown;
  try {
    value = await toolCtx.mw.callTool(server, tool, callArguments, exec.signal, {
      agent: exec.agent,
      callId: exec.callId,
      ...(exec.rootCallId === undefined ? {} : { rootCallId: exec.rootCallId }),
      // token 即本次调用的身份：子调用以它为 parent，guard 据此区分「模型直呼」与「我方转发」。
      ...(exec.token === undefined ? {} : { parent: exec.token }),
    });
    const durationMs = Date.now() - startTime;
    if (toolCtx.stats?.isEnabled()) {
      toolCtx.stats.recordCall(parsed.server, tool, durationMs, true);
    }
  } catch (error) {
    const durationMs = Date.now() - startTime;
    if (toolCtx.stats?.isEnabled()) {
      // #770-A4：先脱敏再传入（复用 C 快照 + 展开，见 redactedStatsError）；
      // 收集器保持纯，不在内部引 pipeline。回落 undefined 时仍计 errors、不存原文。
      const redacted = redactedStatsError(toolCtx.mw, error);
      if (redacted === undefined) toolCtx.stats.recordCall(parsed.server, tool, durationMs, false);
      else toolCtx.stats.recordCall(parsed.server, tool, durationMs, false, redacted);
    }
    throw error;
  }
  // 交付物 B（A+ 自持图片准入）：远端原始图片块出现时才建模型面投影，按 exec 键控存进表；
  // 无图片（或图片块已是模型面形态）时不建映射，finalizeContent 返回 undefined，继续走 render。
  // 投影基于**这里 return 的 value 的 content**（含 dispatch 的 stale 前置提示），不是渲染产物。
  // 任何拒绝都只在投影里落诊断文本，本函数不因图片面抛错。
  const projection = await projectImageAdmission({
    agent: exec.agent,
    content: callValueContent(value),
    signal: exec.signal,
    faces: toolCtx.faces,
    formatBlock: formatCallContentBlock,
  });
  if (projection !== undefined) toolCtx.projections.set(exec, projection);
  return value;
}

/** 取 `mw.callTool` 返回值里的 content 数组（非数组/缺席 → 空表：不可能有图片块）。 */
function callValueContent(value: unknown): readonly unknown[] {
  const content = (value as { content?: unknown } | undefined)?.content;
  return Array.isArray(content) ? content : [];
}

function buildCallTool(toolCtx: MiddlewareToolContext, callTimeoutMs: number): ToolDefinition {
  return {
    name: "ws_mcp_call",
    description:
      "Invoke an MCP tool in the current workspace (executes on live server). Verify parameter schema with ws_mcp_detail beforehand (can invoke directly if server and tool are known); obtain user consent before write or sensitive operations.",
    parameters: {
      type: "object",
      properties: {
        server: {
          type: "string",
          description: "Required: @<root>/<server> full name (from ws_mcp_search / ws_mcp_list)",
        },
        tool: {
          type: "string",
          description: "Required: bare remote tool name (from ws_mcp_search / ws_mcp_list)",
        },
        arguments: {
          type: "object",
          additionalProperties: true,
          description:
            "Arguments matching inputSchema from ws_mcp_detail (properties/required/enum/description); check with ws_mcp_detail when uncertain",
        },
      },
      required: ["server", "tool"],
    },
    output: {
      schema: {
        type: "object",
        properties: {
          content: { type: "array", items: {} },
          structuredContent: {},
        },
        required: ["content"],
        additionalProperties: false,
      },
      render: renderCallOutput,
    },
    isConcurrencySafe: () => true,
    // 外层超时由调用方现算递入（#935：max(全量源) + 25s 内部尾；旧 55s 写死值已删）。
    timeoutMs: callTimeoutMs,
    /**
     * 官方 `applyFinalContent` 接缝：把本包自持的图片准入投影换进模型面（返回 `undefined`
     * 则保留原内容 = 继续走 `render`）。命中即删——每次执行只消费一次。`isError` 时把内容
     * 交回宿主：错误面不该被换面。
     */
    finalizeContent(exec, result) {
      const projection = toolCtx.projections.get(exec);
      if (projection === undefined) return undefined;
      toolCtx.projections.delete(exec);
      if (result.isError === true) return undefined;
      return projection;
    },
    execute: (args, exec) => executeCall(toolCtx, args, exec),
  };
}

// ---------------------------------------------------------------------------
// 3. ws_mcp_list
// ---------------------------------------------------------------------------

function formatListTool(t: Record<string, unknown>): string {
  return `  - ${String(t.tool ?? "")}: ${String(t.description ?? "")}`;
}

function formatListServerEntry(entry: Record<string, unknown>): string {
  const server = String(entry.server ?? "");
  const tools = Array.isArray(entry.tools) ? (entry.tools as Array<Record<string, unknown>>) : [];
  const head =
    tools.length > 0
      ? `${server} (${tools.length} tools):\n${tools.map(formatListTool).join("\n")}`
      : `${server} (0 tools)`;
  const disabled = entry.disabled === true ? " [disabled]" : "";
  const unavailable =
    typeof entry.unavailable === "string" && entry.unavailable !== ""
      ? ` [unavailable: ${entry.unavailable}]`
      : "";
  const truncated =
    entry.toolsTruncated === true
      ? " [toolsTruncated: tool count reached limit, increase perServerLimit to retry]"
      : "";
  return `${head}${disabled}${unavailable}${truncated}`;
}

function renderListOutput(_args: unknown, value: unknown) {
  const v = (value ?? {}) as {
    workspace?: unknown;
    servers?: Array<Record<string, unknown>>;
    totalServers?: unknown;
    totalTools?: unknown;
    toolsTruncated?: unknown;
    message?: unknown;
  };
  const servers = v.servers ?? [];
  const lines = servers.map(formatListServerEntry);
  const prefix = `Workspace ${String(v.workspace ?? "")}: ${String(v.totalServers ?? 0)} servers / ${String(v.totalTools ?? 0)} tools in total`;
  const body =
    lines.length > 0
      ? lines.join("\n\n")
      : String(v.message ?? "(No MCP servers found in current workspace)");
  const truncated =
    v.toolsTruncated === true
      ? "\n(Some server tool lists were truncated; increase perServerLimit if needed)"
      : "";
  return [{ type: "text" as const, text: `${prefix}\n\n${body}${truncated}` }];
}

function parseListParams(args: unknown): { serverFilter?: string; toolLimit: number } {
  const {
    runtime: { LIST_MAX_TOOLS_PER_SERVER },
  } = injectPorts.get();
  const params = (typeof args === "object" && args !== null ? args : {}) as Record<string, unknown>;
  const serverFilter =
    typeof params.server === "string" && params.server !== "" ? params.server : undefined;
  const requested =
    typeof params.perServerLimit === "number"
      ? Math.floor(params.perServerLimit)
      : LIST_DEFAULT_TOOLS_PER_SERVER;
  const toolLimit = Math.max(1, Math.min(requested, LIST_MAX_TOOLS_PER_SERVER));
  return { serverFilter, toolLimit };
}

function resolveEmptyListMessage(
  serverFilter: string | undefined,
  mw: McpMiddleware,
  root: string,
): string {
  if (serverFilter !== undefined) {
    const visible = visibleProjectServers(root);
    const visibleText =
      visible.length > 0
        ? `可见项目级服务器：${visible.join(" / ")}；`
        : "当前工作空间无已发现的项目级服务器；";
    return `没有匹配 server=${JSON.stringify(serverFilter)} 的项目级服务器。${visibleText}全局级服务器不在此列出：请用 ws_mcp_call 按全名访问（全局级写作 @global/<server>，项目级写作 @<root>/<server>；全名从 ws_mcp_list / ws_mcp_search 读），封装定义条目同样经它访问`;
  }
  // 单池后「无项目单元」不再等于「只有项目级可见」：@global 单元同样会被查询。
  return "当前工作空间没有可用 MCP 服务器（项目级与全局均未发现；若刚添加配置，请稍后重试）";
}

async function resolveListWithoutUnit(
  mw: McpMiddleware,
  root: string,
  serverFilter: string | undefined,
  toolLimit: number,
) {
  const {
    catalog: { listCatalog },
  } = injectPorts.get();
  // 单池：单元缺失也查 @global（原「非 all 模式 → 只报项目级未配置」的分支已删）。
  const globalUnit = await mw.projectUnitFor("@global");
  if (globalUnit !== undefined) await waitForDiscovery(globalUnit);
  return listCatalog(
    mw.units,
    ["@global"],
    serverFilter,
    toolLimit,
    "当前工作空间没有可用 MCP 服务器（项目级与全局均未发现；若刚添加配置，请稍后重试）",
    mw.disabledTools,
  );
}

async function executeList(
  toolCtx: MiddlewareToolContext,
  args: unknown,
  exec: { signal?: AbortSignal; agent?: unknown },
) {
  const root = await toolCtx.resolveRoot(exec.agent);
  if (root === undefined) throw new Error("ws_mcp_list: 无法确定工作空间，请先选择工作区");
  const { serverFilter, toolLimit } = parseListParams(args);
  if (toolCtx.stats?.isEnabled()) {
    toolCtx.stats.recordList(serverFilter);
  }
  const roots = visibleMiddlewareRoots(root);
  const unit = await toolCtx.mw.projectUnitFor(root);
  if (unit === undefined) {
    return resolveListWithoutUnit(toolCtx.mw, root, serverFilter, toolLimit);
  }
  // 等待 in-flight 连接/发现（预算内），再搜索。对可见全部单元
  // （含 @global 首次触达）都等待——否则全局目录首次为空（P1-3 修复）。
  for (const visible of roots) {
    const visibleUnit = visible === root ? unit : await toolCtx.mw.projectUnitFor(visible);
    if (visibleUnit !== undefined) await waitForDiscovery(visibleUnit);
  }
  const {
    catalog: { listCatalog },
  } = injectPorts.get();
  const result = listCatalog(
    toolCtx.mw.units,
    roots,
    serverFilter,
    toolLimit,
    "",
    toolCtx.mw.disabledTools,
  );
  // A1：带 serverFilter 过滤后 0 命中 → message 可归因（不谎报「未配置」）。
  if (result.servers.length === 0) {
    result.message = resolveEmptyListMessage(serverFilter, toolCtx.mw, root);
  }
  return result;
}

function buildListTool(toolCtx: MiddlewareToolContext): ToolDefinition {
  const {
    runtime: { LIST_MAX_TOOLS_PER_SERVER },
  } = injectPorts.get();
  return {
    name: "ws_mcp_list",
    description:
      "List all MCP servers and their complete tool inventories in current workspace (not truncated by search limit). Returns full server names, tool names, and descriptions. Does not return inputSchema (use ws_mcp_detail for full schemas). Includes project-level and global servers.",
    parameters: {
      type: "object",
      properties: {
        server: {
          type: "string",
          description:
            "Optional: @<root>/<server> full name or bare name filter (error if root is not in current workspace)",
        },
        perServerLimit: {
          type: "number",
          description: `Optional: max tools per server (default ${LIST_DEFAULT_TOOLS_PER_SERVER}, max ${LIST_MAX_TOOLS_PER_SERVER}; sets toolsTruncated=true when exceeded)`,
        },
      },
    },
    output: {
      schema: {
        type: "object",
        properties: {
          workspace: { type: "string" },
          servers: { type: "array", items: {} },
          totalServers: { type: "number" },
          totalTools: { type: "number" },
          toolsTruncated: { type: "boolean" },
          message: { type: "string" },
        },
        required: ["workspace", "servers", "totalServers", "totalTools", "toolsTruncated"],
        additionalProperties: false,
      },
      render: renderListOutput,
    },
    isConcurrencySafe: () => true,
    execute: (args, exec) => executeList(toolCtx, args, exec),
  };
}

