    const unit2 = makeUnit({
      root: "@global",
      catalog: new Map([
        [
          "cg",
          {
            discoveredAt: Date.now(),
            tools: new Map([["cg_node", { description: "d", inputSchema: {} }]]),
          },
        ],
        [
          "storeSrv",
          {
            discoveredAt: Date.now(),
            tools: new Map([["t1", { description: "d", inputSchema: {} }]]),
          },
        ],
      ]),
